        pdeque->fin = pdeque->fin->prev; // Déplace le pointeur de fin au chainon précédent
        free(tmp); // Libère la mémoire de l'ancien dernier chainon
        if (pdeque->fin == NULL) // Si la deque devient vide après la suppression
        {
