int motExistant(Arbre *a, char *mot) {
    if (a == NULL || mot == NULL) {
        return 0; 
    }

    if (*mot == '\0') {
        return 1; 
    }

    if (*mot == a->value) {
        return motExistant(a->fg, mot + 1) || motExistant(a->fd, mot + 1);
    }

    return motExistant(a->fg, mot) || motExistant(a->fd, mot);
}
